NAME = 'SloKJV: Slovenian translation of Holy Bible King James Version (1769)'
BOOK = 'II Peter'

CHAPTERS = {
    1: {
        1: 'Simon Peter, služabnik in apostol Jezusa Kristusa tem, ki so z nami po Božji pravičnosti in našem Odrešeniku Jezusu Kristusu dosegli podobno dragoceno vero:',
        2: '›Milost in mir naj se vam pomnožita prek spoznanja Boga in Jezusa, našega Gospoda,',
        3: 'glede na to, kot nam je njegova božanska moč dala vse stvari, ki se nanašajo na življenje in bogaboječnost, prek spoznanja tistega, ki nas je poklical v slavo in moč;',
        4: 'po katerih so nam dane silno velike in dragocene obljube, da bi bili po teh lahko soudeleženci božanske narave, ko smo pobegnili propadljivosti, ki je na svetu prek poželenja.‹',
        5: 'In poleg tega darujte vso marljivost, dodajte svoji veri krepost, in kreposti spoznanje,',
        6: 'in spoznanju zmernost, in zmernosti potrpežljivost, in potrpežljivosti bogaboječnost,',
        7: 'in bogaboječnosti bratsko prijaznost, in bratski prijaznosti ljubezen.',
        8: 'Kajti če so te stvari v vas in [so] obilne, vas naredijo, da ne boste niti jalovi niti brez sadu v spoznanju našega Gospoda Jezusa Kristusa.',
        9: 'Toda komur te stvari primanjkujejo, je slep in kratkoviden in je pozabil, da je bil očiščen od svojih starih grehov.',
        10: 'Bratje, zatorej si raje prizadevajte, da storite svojo poklicanost in izvoljenost zanesljivo; kajti če te stvari počnete, nikoli ne boste padli,',
        11: 'kajti tako vam bo razkošno odprt vstop v večno kraljestvo našega Gospoda in Odrešenika Jezusa Kristusa.',
        12: 'Zato ne bom nemaren, da vas ne bi vedno opominjal o teh stvareh, čeprav jih veste in ste utrjeni v pričujoči resnici.',
        13: 'Da, mislim, da je primerno, dokler sem v tem šotoru, da vas razvnamem s tem, da vas spomnim,',
        14: 'vedoč, da bom moral v kratkem odložiti ta svoj šotor, kakor mi je pokazal naš Gospod Jezus Kristus.',
        15: 'Poleg tega si bom prizadeval, da boste po mojem odhodu [s sveta] lahko imeli te stvari vedno v spominu.',
        16: 'Kajti ko smo vam dali spoznati moč in prihod našega Gospoda Jezusa Kristusa, nismo sledili pretkano izmišljenim bajkam, ampak smo bili očividci njegovega veličanstva.',
        17: 'Kajti od Boga Očeta je prejel čast in slavo, ko je iz odlične slave k njemu prišel takšen glas: »Ta je moj ljubljeni Sin, v katerem sem zelo zadovoljen.«',
        18: 'In ta glas, ki je prišel z neba, smo slišali, ko smo bili z njim na sveti gori.',
        19: 'Imamo tudi zanesljivejšo preroško besedo; zato pravilno delate, da pazite nanjo kakor na svetilko, ki sije na temnem kraju, dokler ne zasveti zora in v vaših srcih ne vzide zvezda danica;',
        20: 'vedoč najprej to, da nobena prerokba iz pisem ni iz kakršnekoli osebne razlage.',
        21: 'Kajti prerokba v starih časih ni prišla s človeško voljo, temveč so sveti Božji možje govorili, kakor bi bili spodbujeni s Svetim Duhom.',
    },
    2: {
        1: 'Vendar so bili lažni preroki tudi med ljudmi, točno tako bodo med vami lažni učitelji, ki bodo na skrivnem vnašali preklenska krivoverstva in celó tajili Gospoda, ki jih je odkupil ter si nase nakopali hiter propad.',
        2: 'In mnogi bodo sledili njihovim pogubnim potem; zaradi katerih se bo obrekovala pot resnice.',
        3: 'In zaradi pohlepnosti bodo s hlinjenimi besedami iz vas naredili trgovsko blago; katerih sodba se sedaj že dolgo ne obotavlja in njihovo prekletstvo ne dremlje.',
        4: 'Kajti če Bog ni prizanesel angelom, ki so grešili, temveč jih je vrgel navzdol v pekel in jih izročil verigam teme, da bodo pridržani do sodbe,',
        5: 'in ni prizanesel staremu svetu, temveč rešil Noeta, osmo osebo, oznanjevalca pravičnosti, ko je poslal potop na svet brezbožnih;',
        6: 'in spremenil mesti Sódome in Gomóre v pepel, ju je obsodil z uničenjem in ju naredil zgled tem, ki naj bi kasneje brezbožno živeli;',
        7: 'in osvobodil pravičnega Lota, prizadetega z umazanim razgovorom zlobnih;',
        8: '(kajti ta pravičen mož je prebival med njimi in z videnjem in slišanjem iz dneva v dan z njihovimi nezakonitimi dejanji mučil svojo pravično dušo.)',
        9: 'Gospod ve kako bogaboječega osvoboditi iz preizkušenj in nepravične prihraniti za dan sodbe, da bodo kaznovani.',
        10: 'Toda predvsem te, ki hodijo za mesom v nečistosti poželenja in prezirajo vlado. Predrzni so, svojevoljni, ne bojijo se hudobno govoriti o dostojanstvih.',
        11: 'Medtem ko angeli, ki so večji v moči in mogočnosti, pred Gospoda ne prinašajo posmehljivih obtožb zoper njih.',
        12: 'Toda ti, kot naravne okrutne živali, narejene, da so ujete in uničene, govorijo hudobno o stvareh, ki jih ne razumejo; in v svoji lastni pokvarjenosti bodo popolnoma propadli;',
        13: 'in prejeli bodo nagrado nepravičnosti, kakor tisti, ki imajo za užitek razgrajanje podnevi. Madeži so in izvržki, ki se zabavajo s svojimi lastnimi zavajanji, medtem ko se gostijo z vami;',
        14: 'ki imajo oči, polne zakonolomstva in ki ne morejo prenehati z grehom; ki zapeljujejo omahljive duše, srce pa so urili s pohlepnimi navadami; prekleti otroci;',
        15: 'ki so zapustili pravo pot in zašli ter sledili Beórjevemu sinu Bileámu, ki je vzljubil plačila nepravičnosti;',
        16: 'toda za svojo krivičnost je bil oštet; nemi osel, govoreč s človeškim glasom, je preprečil prerokovo norost.',
        17: 'Ti so vodnjaki brez vode, oblaki, ki so nošeni z viharjem, ki jim je večno prihranjena zamegljena črnina.',
        18: 'Kajti ko govorijo velike, napihnjene besede ničevosti, privabljajo s poželenji mesa, skozi mnoge razuzdanosti te, ki so zares pobegnili pred temi, ki živijo v zmoti.',
        19: 'Medtem ko jim obljubljajo svobodo, [pa] so oni sami služabniki izprijenosti. Kajti od česar je človek premagan, od istega je priveden v sužnost.',
        20: 'Kajti če so potem, ko so prek spoznanja Gospoda in Odrešenika Jezusa Kristusa pobegnili umazanostim sveta, bili ponovno vpleteni vanje in premagani, je zadnji konec z njimi slabši kakor začetek.',
        21: 'Kajti zanje bi bilo bolje, da ne bi spoznali poti pravičnosti, kakor pa, potem ko so jo spoznali, da se obrnejo od svete zapovedi, ki jim je bila izročena.',
        22: 'Toda to se jim je zgodilo glede na resničen pregovor: ›Pes se ponovno obrne k svojemu lastnemu izbljuvku; in svinja, ki je bila umita, k svojemu valjanju v blatu.‹',
    },
    3: {
        1: 'Ljubljeni, sedaj vam pišem torej to drugo poslanico; v katerih obeh sem vaše čiste ume razvnel z načinom spominjanja,',
        2: 'da boste lahko razmišljali o besedah, ki so bile prej izgovorjene po svetih prerokih in o zapovedi od nas, apostolov Gospoda in Odrešenika.',
        3: 'Vedite najprej to, da bodo v poslednjih dneh prišli porogljivci, ki bodo hodili za svojimi lastnimi poželenji',
        4: 'ter govorili: »Kje je obljuba njegovega prihoda? Kajti odkar so očetje zaspali, se vse stvari nadaljujejo, kakor so bile od začetka stvarstva.«',
        5: 'Kajti oni tega nočejo spoznati, da je bilo po Božji besedi nebo od davnine in [da] zemlja sestoji iz vode in v vodi.',
        6: 'S čimer je bil svet, ki je bil takrat, preplavljen z vodo, uničen.',
        7: 'Toda nebo in zemlja, ki sta sedaj, sta po isti besedi držana v rezervi, prihranjena ognju za dan sodbe in pogube brezbožnih ljudi.',
        8: 'Toda ljubljeni, ne bodite nevedni o tej eni stvari, da je en dan z Gospodom kakor tisoč let in tisoč let kakor en dan.',
        9: 'Gospod ni počasen glede svoje obljube, kakor nekateri ljudje razumejo počasnost, temveč je do nas potrpežljiv, ne voljan, da bi se kdorkoli pogubil, temveč da bi vsi prišli do kesanja.',
        10: '§ Toda Gospodov dan bo prišel kakor tat v noči; v kateri bo nebo preminilo z velikim hrupom in prvine se bodo stopile z gorečo vročino; tudi zemlja in dela, ki so na njej, bodo sežgana.',
        11: 'Ker se bodo torej vse te stvari raztopile, kakšna vrsta oseb morate biti v vsem svetem vedênju in bogaboječnosti,',
        12: 'da pričakujete in hitite k prihajanju Božjega dne, ko se bo nebo goreče stopilo in se bodo prvine stopile z gorečo vročino?',
        13: 'Kljub temu pa mi, glede na njegovo obljubo, pričakujemo novo nebo in novo zemljo, kjer prebiva pravičnost.',
        14: 'Torej, ljubljeni, glede na to, da pričakujete takšne stvari, si prizadevajte, da vas bo lahko našel v miru, brez madeža in brez krivde.',
        15: 'In upoštevajte, da je potrpežljivost našega Gospoda rešitev duš; kakor vam je napisal tudi naš ljubljeni brat Pavel, glede na modrost, ki mu je bila dana;',
        16: 'kakor je tudi v vseh njegovih poslanicah, kjer v njih govori o teh stvareh; v katerih so nekatere stvari težke za razumevanje, ki jih tisti, ki so nepoučeni in omahljivi, pačijo, kakor počno tudi drugim pismom, v svoje lastno uničenje.',
        17: 'Vi torej, ljubljeni, glede na to, da vidim, da poprej poznate te stvari, se varujte, da ne bi tudi vi, zavedeni z zmoto zlobnih, odpadli od svoje lastne neomajnosti.',
        18: 'Temveč rastite v milosti in v spoznanju našega Gospoda in Odrešenika Jezusa Kristusa. Njemu bodi slava tako sedaj in na veke. Amen.',
    },
}
